#!/usr/bin/env bash
set -euo pipefail
H="$(hostname -s)"; K=(k3s kubectl); f=0; ok(){ echo "PASS: $*"; }; bad(){ echo "FAIL: $*" >&2; f=1; }; [[ ${EUID} -eq 0 ]] || exit 1; [[ "$H" == "${DR_PRODUCTION_HOSTNAME:-guiosoft-info}" ]] && ok hostname || bad hostname; ip -o -4 addr show scope global|awk '{print $4}'|cut -d/ -f1|grep -Fxq "${DR_PRODUCTION_IP:-192.168.88.9}" && ok ip || bad ip; for c in k3s restic python3; do command -v "$c" >/dev/null && ok "$c" || bad "$c"; done; "${K[@]}" get --raw=/readyz >/dev/null 2>&1 && ok api || bad api; for s in kube-prometheus-stack-grafana tempo loki prometheus-kube-prometheus-stack-prometheus; do r="$("${K[@]}" -n monitoring get sts "$s" -o jsonpath='{.spec.replicas}' 2>/dev/null||true)"; [[ "$r" =~ ^[1-9][0-9]*$ ]] && ok "$s replicas=$r" || bad "$s"; done; for x in /etc/k3s-backup/r2.env /etc/k3s-backup/restic.repository /etc/k3s-backup/restic.password; do [[ -s "$x" ]] && ok "$x" || bad "$x"; done; [[ -d /mnt/store1/k3s/local-path ]] && ok pv-root || bad pv-root; [[ -d /srv/k3s/backups/k3s ]] && ok staging || bad staging; ((f==0)) || { echo "Consistent-backup readiness: FAIL" >&2; exit 1; }; echo "Consistent-backup readiness: PASS"; echo "No state changed."
